INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Donkey Kong Junior', 'Donkey Kong Junior is the direct sequel to Donkey Kong. In this game, Mario plays the antagonist, finally having captured Donkey Kong, and has put the ape in a locked cage. As Donkey Kong Jr., players will have to make their way through four different levels (Vines, Springboard, Chains and Mario''s Hideout) in an attempt to find keys to free the little monkey''s father.' FROM games WHERE igdb_id = 1087 ON CONFLICT (game_id, language_code) DO NOTHING;
