INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Millipede', 'Millipede is a 1982 arcade game by Atari, Inc. and is the sequel to the arcade hit, Centipede. The objective of the game is to score as many points as possible by destroying all segments of the millipede as it moves toward the bottom of the screen, as well as destroying and avoiding other enemies. The game is played with a trackball and a single fire button, which can be held down for rapid-fire. The game is over when the player''s last life is lost.' FROM games WHERE igdb_id = 4604 ON CONFLICT (game_id, language_code) DO NOTHING;
