INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demons to Diamonds', 'Players attempt to shoot demons in a "cosmic carnival" and then pick up the diamonds left behind by them, while dodging shots from enemy skulls. The player operates a laser base at the bottom of a multi-row playfield, using the paddle controller to move it from side to side and the controller''s action button to fire a laser beam vertically up the playfield. The player can control how far onto the playfield the beam advances by releasing the button at the desired height. The player receives one point for each demon and ten points for each diamond successfully shot. Points are multiplied by the distance from the base to the target. For example, a demon shot one row above the player is worth one point, while a demon shot four rows above the player is worth four points.
