INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cosmic Ark', 'The sun of Alpha Ro is fading fast! Soon it will flicker out. The Cosmic Ark races to save creatures from doomed planets in that solar system. Meteor showers bombard the Ark, threatening its Atlantean crew - and planetary defense systems make this mission of mercy doubly treacherous! Time and energy slip away- work fast or these defenceless little beasties will disappear for all time.' FROM games WHERE igdb_id = 8466 ON CONFLICT (game_id, language_code) DO NOTHING;
