INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Liberator', 'Liberator is commonly described as the opposite of Missile Command. The objective of Missile Command is to defend your bases from a space-based attack. Liberator''s objective is the exact opposite, destroy enemy bases as you orbit their planet. Liberator was released by Atari in 1982. The arcade game was not very popular and only 762 arcade machines were ever made.' FROM games WHERE igdb_id = 18456 ON CONFLICT (game_id, language_code) DO NOTHING;
