INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night Stalker', 'Night Stalker (released as "Dark Cavern" on Atari 2600) is a top-down maze shooter designed by Steve Montero and released for the Intellivision console in 1982. Night Stalker was ported to the Atari 2600 as Dark Cavern and released under Mattel''s M Network label. Apple II and IBM PC versions were published in 1983.
