INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Demon Attack', 'Demon Attack is an arcade action game with gameplay similar to Space Invaders. You control a laser cannon at the bottom of the screen, and need to destroy wave after wave of brightly colored demons. The demons bounce around the screen in bizarre patterns, and try to destroy your cannon with bombs or lasers. When you shoot a demon, it will be replaced with another or will split into two smaller demons depending on which wave you are playing. When the required number of demons for the current round is finally destroyed, you can move on to the next, more difficult round.' FROM games WHERE igdb_id = 5670 ON CONFLICT (game_id, language_code) DO NOTHING;
