INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Time Pilot', 'Time Pilot is a multi-directional scrolling shooter and free-roaming aerial combat arcade game designed by Yoshiki Okamoto, released by Konami in 1982, and distributed in the United States by Centuri. Debuting in the golden age of video arcade games, it is a time travel themed game that allowed the player''s plane to freely move across open air space that can scroll indefinitely in all directions. The Killer List of Videogames included Time Pilot in its list of top 100 arcade games of all time.
