INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zork III: The Dungeon Master', 'In the third game of the adventure game series Zork, you are once again a nameless adventurer, only this time you won''t travel through a beautiful magical land, but are immediately cast into a deep dungeon. Like in a dream, you hear a mysterious voice telling you that you have passed all the tests but one. When conscience returns to you, you find yourself on the endless spiral of stairs, with only your trusty lantern near you... will you be able to survive the horrors of the Dungeon?' FROM games WHERE igdb_id = 1946 ON CONFLICT (game_id, language_code) DO NOTHING;
