INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bagman', 25829, '1982-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8i7m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmq2v.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bagman', 'The objective of the game is to maneuver the bagman through various mine shafts, picking up money bags and placing them in a wheelbarrow at the surface of the mine. The player must avoid pursuing guards, moving ore carts, and descending elevators. The player may temporarily stun the guards by striking them with a pickaxe or by dropping money bags on them when they are below the player on the same ladder. The player may move between the three screens which make up the level via shafts and on the surface.' FROM games WHERE igdb_id = 25829 ON CONFLICT (game_id, language_code) DO NOTHING;
