INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tutankham', 'Tutankham is a combination of the maze, action and shoot ''em up genres. Taking on the role of an explorer grave robbing Tutankhamun''s tomb, the player is chased by creatures such as asps, vultures, parrots, bats, dragons, and even curses, all that kill the player on contact. The explorer can fight back by firing lasers at the creatures, but he can only cover the left and right directions. The player is also endowed with a single screen-clearing "flash bomb" per level or life. Finally, each level has warp zones that teleport the player around the level, which enemies cannot use.
