INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('super-pac-man', 21681, '1982-09-26', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ta6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scehw8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super Pac-Man', 'Super Pac-Man is a game in Namco''s Pac-Man family, but instead of gobbling up dots, Pac is required to eat fruit and prizes, such as apples, bunches of bananas, doughnuts, hamburgers, fried eggs, ears of corn, sneakers, pieces of cakes, raspberries, limes, cups of coffee, mushrooms, Galaxians, bells, and shamrocks. Most of these items are hidden in passages that have locked doors at either entrance, and in order to unlock the doors, Pac needs to eat the key that is closest to the passage that he wishes to unlock. As usual, ghosts will keep chasing Pac around the maze until he has lost all his lives. However, Pac can enter the warp tunnels at either side of the maze to lose the ghosts quickly.
