INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Haunted House', 'Haunted House is an Atari 2600 video game written by James Andreasen and published by Atari, Inc. in February 1982. The player, represented by a pair of eyes, must navigate the haunted mansion of the late Zachary Graves to recover the three pieces of an urn. The game has been identified as one of the earliest examples of the survival horror genre.' FROM games WHERE igdb_id = 4909 ON CONFLICT (game_id, language_code) DO NOTHING;
