INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bump ''n'' Jump', 'Bump ''n'' Jump is an overhead-view vehicular combat game developed by Data East and originally released in Japan as "Burnin'' Rubber". The arcade version was available as both a dedicated board and as part of Data East''s DECO Cassette System. It was distributed in North America by Bally Midway. The goal is to drive to the end of a level while bumping enemy vehicles into the sides of the track and jumping over large obstacles such as bodies of water.
