INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Horace Goes Skiing', 'In 1982 Tang also produced Horace Goes Skiing. In it, Horace must cross a dangerous road teeming with traffic to rent out a pair of skis, à la Frogger, get back over the road and successfully navigate a ski course.
