INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Frog Bog', 'Frog Bog is a video game released by Mattel Electronics in 1982, developed by APH Technological Consulting. Players control a frog on a lily pad, competing to catch the most insects within a three-minute time limit. The challenge involves using the frog''s tongue to capture flying insects while avoiding falling into the water, which would waste valuable time.
