INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Megamania', 'In Megamania, the gameplay resembles that of Space Invaders. Rather than being aliens or spaceships, however, the enemies in this game are various objects such as hamburgers, bow ties, and steam irons. The object is to shoot them down before the energy bar at the bottom of screen is depleted, all while avoiding the oncoming enemies and their own projectiles attacks. Each of the enemies fly in select patterns and as soon as they hit the bottom of the screen, they re-appear at the top until shot by the player. The player''s spacecraft depicted in the game is a cross between the U.S.S. Enterprise and Klingon battlecruiser from the Star Trek universe.
