INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moon Patrol', 'Moon Patrol is a side-scrolling shooter that puts players at the controls of a six-wheeled moon rover that can jump and shoot. The goal is to move through the entire course as quickly as possible while shooting enemies for additional points. Cannons are mounted on the front and top of the vehicle, and both fire simultaneously when the fire button is pressed. Rocks, mines, and pits in the course prevent you from just holding to the right for maximum speed. Rocks and mines can be shot, but pits must be jumped. Some enemies fire shots that create new pits in the course, forcing players to react quickly.' FROM games WHERE igdb_id = 12314 ON CONFLICT (game_id, language_code) DO NOTHING;
