INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Karate', 'Karate is a video game for the Atari 2600 originally published by Ultravision in 1982 for NTSC systems, then re-released in the latter half of the 1980s by Froggo. Supposedly the game was designed by black belt Joseph Amelio. In 1991, Digital Press chose Karate as one of the worst Atari 2600 games of all time.' FROM games WHERE igdb_id = 250219 ON CONFLICT (game_id, language_code) DO NOTHING;
