INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('barnstorming', 18032, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co93cf.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq3y8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Barnstorming', 'The player must pilot a biplane through a series of barns in the shortest time possible while dodging windmills, weather vanes, and geese. Bumping into anything slows down the plane for a couple of seconds, increasing the overall time. There are four levels of play determined by the game select switch. Game 1 is Hedge Hopper (10 barns), game 2 is Crop Duster (15 barns), game 3 is Stunt Pilot (15 barns), and game 4 is Flying Ace (25 barns). In the first three games, the course layout of barns, windmills, and even geese do not change, making it easy to memorize the layout. Game 4 is the only game with a random course.' FROM games WHERE igdb_id = 18032 ON CONFLICT (game_id, language_code) DO NOTHING;
