INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tron', 'Tron is a coin-operated arcade video game manufactured and distributed by Bally Midway in 1982. It is based on the Walt Disney Productions motion picture Tron released in the same year. The game consists of four subgames inspired by the events of the science fiction film. It features some characters and equipment seen in the film, e.g. the Light Cycles, battle tanks, the Input/Output Tower.' FROM games WHERE igdb_id = 5247 ON CONFLICT (game_id, language_code) DO NOTHING;
