INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Telengard', 'Telengard is an earlier example of a "dungeon crawler" role-playing game--albeit with a top-down view- with either real time movement (DOS version) or turn-based movement and turn based combat. Telengard is also played in real time, which means that monsters can attack even when the player''s character is not moving.
