INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Q*bert', 'Q*bert was a popular arcade game that was released on a large number of consoles in the early 1980s. It was developed and published by Gottlieb, and became their most successful game. The concept serves as a precursor to the isometric platformer genre, where the title character must work to turn all cubes to a certain colour in a psuedo-3D world, made 3D through isometric graphics in the same way that the Penrose Stairs was made. The game was widely successful and has become a highly recognizable brand of the 1980s gaming era.' FROM games WHERE igdb_id = 1980 ON CONFLICT (game_id, language_code) DO NOTHING;
