INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deadline', 'Deadline is an interactive fiction computer game published by Infocom in 1982. Written by Marc Blank, it was one of the first murder mystery interactive fiction games. Like most Infocom titles, Deadline was created using ZIL, which allowed the easy porting of the game to popular computer platforms of the time such as the Apple II and the Commodore 64. It is Infocom''s third game.
