INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ultima II: The Revenge of the Enchantress', 'After obtaining aid from the lords of the realm in Ultima I, your character travels back in time, locates the mad wizard Mondain, slays him, and ends his reign of terror. In Ultima II: Revenge of the Enchantress, Mondain''s protégé, Minax, who studied the mad wizard''s teachings and writings, returns to wreak vengeance on the person who slew her teacher and lover -- you. And, instead of waiting for you to return to her native land of Sosaria, she wreaks havoc on your own Earth.
