INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Football Manager', 'The first football management simulator, many of the hallmarks of the incredibly complex games which exist in this genre today are found in embryonic form here. Club finances, player transfers, basic tactics, and perhaps most importantly of all, excellent white noise crowd sounds when your team scored.' FROM games WHERE igdb_id = 23064 ON CONFLICT (game_id, language_code) DO NOTHING;
