INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('starmaster', 18033, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/unsqsl9ojtpbetjesm6m.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scq531.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Starmaster', 'In the game the player pilots a starfighter, with the purpose of destroying a number of enemy ships before they destroy four friendly starbases. Gameplay is presented mostly in first person cockpit view, which is achieved with surprisingly good effect given the 2600''s primitive graphics capabilities. The starfighter carries laser weapons, shields, and a faster-than-light drive. The fighter also carries a limited energy supply, which is drained by firing the lasers, being hit by enemy fire, warping, or simply flying around. If the ship''s energy drops to zero it is destroyed, and the game ends. Enemy fire can knock out the fighter''s subsystems (such as weapons) on top of draining energy. The game "universe" is a square-shaped galaxy mapped into a grid of 36 sectors. Each sector can be home to some enemy ships, a starbase, both, or nothing. The player "warps" the fighter to a sector to engage enemy ships; once they are all destroyed, the player moves on to another. The player can also warp to a sector with a starbase, and dock with it (a rather tricky process) to replenish energy and repair damaged subsystems. Enemy ships in turn maneuver through the galaxy as they home in to destroy the starbases. The game is won when all enemy ships are destroyed, or lost if either the player''s fighter or all four starbases are destroyed.' FROM games WHERE igdb_id = 18033 ON CONFLICT (game_id, language_code) DO NOTHING;
