INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('atlantis', 5658, '1982-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co5vjg.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/si8hs5frfj3aowp63yas.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Atlantis', 'The lost city of Atlantis is under attack! Wave after wave of Gorgon vessels are approaching, each armed with weapons capable of destroying a part of the city. You are in charge of the command posts at the edges of the city and need to defend it from the invaders. The various gorgon craft will keep flying by on the screen in varying numbers and in different flight patterns. At first they fly high in the sky but then progressively lower. If an enemy makes it low enough before you destroy it, it will use it''s weapons and destroy one of the buildings in Atlantis. As you progress in the game, the enemy craft will keep increasing in speed. The game ends when all remaining buildings in the city have been destroyed.' FROM games WHERE igdb_id = 5658 ON CONFLICT (game_id, language_code) DO NOTHING;
