INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shamus', 'Shamus is a shooter with light action-adventure game elements written by Cathryn Mataga and published by Synapse Software. The original Atari 8-bit computer version was released on disk and tape in 1982. According to Synapse co-founder Ihor Wolosenko, Shamus made the company famous by giving it a reputation for quality. "Funeral March of a Marionette", the theme song from Alfred Hitchcock Presents, plays on the title screen.' FROM games WHERE igdb_id = 18659 ON CONFLICT (game_id, language_code) DO NOTHING;
