INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wizardry: Knight of Diamonds - The Second Scenario', 'Are you ready to take the next step into the world of Wizardry? A step so dangerous, the mere utterance of a spell can decimate the entire city of Llylgamyn. Knight of Diamonds is the Second Scenario in the Wizardry Master Series, the fantasy role-playing simulation for the Nintendo Entertainment System. In Wizardr Knight of Diamonds, only the bravest may venture through murky dungeons more dangerous than any ever encountered by earthly mortals. Only the most cunning may recover the magical Staff of Gailda and save the city of Llylgamyn.' FROM games WHERE igdb_id = 2865 ON CONFLICT (game_id, language_code) DO NOTHING;
