INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zaxxon', 'Zaxxon is a 1982 isometric shooter arcade game developed and released by Sega. The game gives the player the experience of flying a fighter craft through a fortress while shooting at enemy entities (missiles, enemy gunfire, etc.) The object of the game is to hit as many targets as possible without being shot down or running out of fuel, which can be replenished paradoxically, by blowing up fuel drums.' FROM games WHERE igdb_id = 2753 ON CONFLICT (game_id, language_code) DO NOTHING;
