INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Loco-Motion', 'Loco-Motion is basically an updated version of a sliding block puzzle game where the player can move pieces horizontally or vertically within a frame to complete a picture. However, the presence of a constantly moving locomotive complicates matters. The player controls the playfield and the aim is to guide the locomotive around the tracks to collect the passengers waiting at the stations located around the edges of the screen.
