INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Prix', 'The player drives a Formula One car in a time trial on one of four race tracks, each of which has a different difficulty level. Difficulty is gauged by the length of the course, the number of cars and oil slicks on the track, and the number of bridges to cross. The player views the race from a top-down perspective, and the screen scrolls from right to left. The player''s car maneuvers only on a vertical axis, and loses a little speed when it does so. The joystick''s button is the throttle: Depressing it accelerates, and releasing it decelerates. Pressing the joystick leftward applies the brake. The transmission audibly shifts as the player''s car accelerates and decelerates. Grand Prix is a time trial, and the competing cars are obstacles rather than competition for the finish line. The player''s car can easily outpace the other cars, but if it collides with one, its speed drops lower than that of the impacted car. Driving over an oil slick causes the player''s car to skid slightly sideways, but does not slow it down. Once every scale mile, the player crosses a narrow bridge over blue water. Colliding with any wall of the bridge stops the car, and the player must slowly gain speed to continue.' FROM games WHERE igdb_id = 18103 ON CONFLICT (game_id, language_code) DO NOTHING;
